(5434701, 781652, 98141, '<td valign="top">Technically sound, beautiful color choices. I think a rotation clockwise 90 degrees would give a really neat chandelier effect.</td>', 'Technically sound, beautiful color choices. I think a rotation clockwise 90 degrees would give a really neat chandelier effect.', '2009-04-13 11:29:27.000000', NULL, 1),
(5434703, 781132, 98141, '<td valign="top">I think the shadows are a bit distracting and thte white background should be whiter to make the colors really pop. It seems like all the colors got together to take out the black and white. Composition is a bit dull as well.</td>', 'I think the shadows are a bit distracting and thte white background should be whiter to make the colors really pop. It seems like all the colors got together to take out the black and white. Composition is a bit dull as well.', '2009-04-13 11:31:06.000000', NULL, 1),
(5434704, 781294, 98141, '<td valign="top">Really neat effect with the light on the drops, not sure if that was added in post or not, but I like it.</td>', 'Really neat effect with the light on the drops, not sure if that was added in post or not, but I like it.', '2009-04-13 11:31:51.000000', NULL, 1),
(5434706, 781176, 98141, '<td valign="top">Love love love the background, the different shades of color all blending together like that.</td>', 'Love love love the background, the different shades of color all blending together like that.', '2009-04-13 11:32:16.000000', NULL, 1),
