(5434722, 781786, 98141, '<td valign="top">Very cute concept, love the execution.</td>', 'Very cute concept, love the execution.', '2009-04-13 11:39:46.000000', NULL, 1),
(5434723, 781395, 98141, '<td valign="top">I think the shadows here are just right: soft, but with strong edges and they add a bit of depth to it.</td>', 'I think the shadows here are just right: soft, but with strong edges and they add a bit of depth to it.', '2009-04-13 11:40:25.000000', NULL, 1),
