INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5435202, 781403, 101256, '<td valign="top">This reviewer''s initial impression was extremely negative, but after returning to the image and figuring out exactly what the image contained, this is a high score. A little too subtle in the abstract sense, this could have been mistaken for a different object in particular with the smoke. On further review though, the image matches the title and is very clever - something to consider when reviewing is not to jump to comclusions as this reviwer did. That may be a problem for this image from a general appeal standpoint, but technically and artistically, this is an outstanding effort on the part of the author and should be viewed as a clever, creative, properly lighted and focused with amazing impact. If there were justice in the one to ten voting system, this would be a perfect ten and if a Hall of Fame existed on DPC, a sure entry into the pantheon of imaginative and illusionary photography. A 10++ from this reviewer - well done.</td>', 'This reviewer''s initial impression was extremely negative, but after returning to the image and figuring out exactly what the image contained, this is a high score. A little too subtle in the abstract sense, this could have been mistaken for a different object in particular with the smoke. On further review though, the image matches the title and is very clever - something to consider when reviewing is not to jump to comclusions as this reviwer did. That may be a problem for this image from a general appeal standpoint, but technically and artistically, this is an outstanding effort on the part of the author and should be viewed as a clever, creative, properly lighted and focused with amazing impact. If there were justice in the one to ten voting system, this would be a perfect ten and if a Hall of Fame existed on DPC, a sure entry into the pantheon of imaginative and illusionary photography. A 10++ from this reviewer - well done.', '2009-04-13 17:07:14.000000', NULL, 1),
(5435203, 781304, 101256, '<td valign="top">The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problems as the image appears to be less than sharp. The DOF could have been used more effectively. A good solid entry into the challenge.</td>', 'The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problems as the image appears to be less than sharp. The DOF could have been used more effectively. A good solid entry into the challenge.', '2009-04-13 17:07:46.000000', NULL, 1),
(5435205, 781618, 66201, '<td valign="top">Best of the water bubble shots. Nice downward-pointing composition.</td>', 'Best of the water bubble shots. Nice downward-pointing composition.', '2009-04-13 17:08:24.000000', NULL, 1),
(5435207, 781752, 101256, '<td valign="top">The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. The DOF could have been used more effectively, but is acceptable as it is. Once again, a clever use of grayscale and color. A good solid entry into the challenge.</td>', 'The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. The DOF could have been used more effectively, but is acceptable as it is. Once again, a clever use of grayscale and color. A good solid entry into the challenge.', '2009-04-13 17:08:45.000000', NULL, 1),
(5435208, 781760, 101256, '<td valign="top">The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problems as the image appears to be over sharpened, but that may be a lighting artifact or the use of an overly stark background. The DOF could have been used more effectively. A good solid entry into the challenge.</td>', 'The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problems as the image appears to be over sharpened, but that may be a lighting artifact or the use of an overly stark background. The DOF could have been used more effectively. A good solid entry into the challenge.', '2009-04-13 17:09:41.000000', NULL, 1),
(5435211, 781770, 55956, '<td valign="top">probably without the "yellow wires" was better.</td>', 'probably without the "yellow wires" was better.', '2009-04-13 17:10:00.000000', NULL, 1),
(5435212, 781460, 101256, '<td valign="top">The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problems as the image appears to be over sharpened, but that may be a lighting artifact. The DOF could have been used more effectively. A good solid entry into the challenge.</td>', 'The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problems as the image appears to be over sharpened, but that may be a lighting artifact. The DOF could have been used more effectively. A good solid entry into the challenge.', '2009-04-13 17:10:03.000000', NULL, 1),
(5435214, 781531, 101256, '<td valign="top">The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge. A couple of minor detail problems as the image appears to be less focused than it should be - the DOF could have been used more effectively. This reviewer checked this on two seperate monitors and it would appear that the color is more a mauve or purple than pink. A good solid entry into the challenge.</td>', 'The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge. A couple of minor detail problems as the image appears to be less focused than it should be - the DOF could have been used more effectively. This reviewer checked this on two seperate monitors and it would appear that the color is more a mauve or purple than pink. A good solid entry into the challenge.', '2009-04-13 17:11:42.000000', NULL, 1),
(5435219, 781696, 101256, '<td valign="top">The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of problems a the DOF could have been used more effectively - the child''s arm virtually disappears around the hand area and that seems to be a glaring defect. A good solid entry into the challenge.</td>', 'The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of problems a the DOF could have been used more effectively - the child''s arm virtually disappears around the hand area and that seems to be a glaring defect. A good solid entry into the challenge.', '2009-04-13 17:13:00.000000', NULL, 1),
(5435220, 781761, 101256, '<td valign="top">The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problems as the image appears to be over sharpened, but that may be a lighting artifact. The DOF could have been used more effectively. A good solid entry into the challenge.</td>', 'The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problems as the image appears to be over sharpened, but that may be a lighting artifact. The DOF could have been used more effectively. A good solid entry into the challenge.', '2009-04-13 17:13:17.000000', NULL, 1),
(5435221, 781794, 101256, '<td valign="top">The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problem such lighting artifact. The DOF could have been used more effectively, but has been controlled well - a touch more DOF to sharpen the right side would have been a plus. A good solid entry into the challenge.</td>', 'The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problem such lighting artifact. The DOF could have been used more effectively, but has been controlled well - a touch more DOF to sharpen the right side would have been a plus. A good solid entry into the challenge.', '2009-04-13 17:14:40.000000', NULL, 1),
(5435222, 780689, 101256, '<td valign="top">The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problem such lighting artifact. The DOF could have been used more effectively, but has been controlled well - a touch more DOF to sharpen the right side would have been a plus. A good solid entry into the challenge.</td>', 'The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problem such lighting artifact. The DOF could have been used more effectively, but has been controlled well - a touch more DOF to sharpen the right side would have been a plus. A good solid entry into the challenge.', '2009-04-13 17:14:50.000000', NULL, 1),
(5435223, 781615, 101256, '<td valign="top">The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problem such lighting artifact. The DOF could have been used more effectively, but has been controlled well. Very clever subject matter - children and puppies have a lot in common. Unusual view of the challenge subject. A good solid entry into the challenge.</td>', 'The image meets the subject matter dead on. A sound demonstration of the creative process in meeting the challenge in a very unusual way. A couple of minor detail problem such lighting artifact. The DOF could have been used more effectively, but has been controlled well. Very clever subject matter - children and puppies have a lot in common. Unusual view of the challenge subject. A good solid entry into the challenge.', '2009-04-13 17:15:57.000000', NULL, 1),
