(5436326, 781783, 80104, '<td valign="top">Nice shot here.  Very interesting with the water droplets.  Too bad you couldn''t get one of the center pencils to get a larger drop to balance things out just a bit more.  However, nicely done.</td>', 'Nice shot here.  Very interesting with the water droplets.  Too bad you couldn''t get one of the center pencils to get a larger drop to balance things out just a bit more.  However, nicely done.', '2009-04-14 11:20:17.000000', NULL, 1),
(5436327, 781601, 80104, '<td valign="top">Interesting shot.  I would have entered the same type of pic had I of competed in this one.</td>', 'Interesting shot.  I would have entered the same type of pic had I of competed in this one.', '2009-04-14 11:20:46.000000', NULL, 1),
(5436329, 781614, 80104, '<td valign="top">The photo just doesn''t do anything for me with the background.</td>', 'The photo just doesn''t do anything for me with the background.', '2009-04-14 11:21:11.000000', NULL, 1),
