(5436332, 781618, 80104, '<td valign="top">This is one of my favorites so far.  Really well done.</td>', 'This is one of my favorites so far.  Really well done.', '2009-04-14 11:21:57.000000', NULL, 1),
(5436333, 781794, 80104, '<td valign="top">Interesting shot.  Wish there was just a tad more DOF to bring out a bit more detail on a few of the closer pencils to the one in focus.</td>', 'Interesting shot.  Wish there was just a tad more DOF to bring out a bit more detail on a few of the closer pencils to the one in focus.', '2009-04-14 11:22:36.000000', NULL, 1),
