(5436336, 781647, 80104, '<td valign="top">Wow really nicely done.  One of my favorites so far.</td>', 'Wow really nicely done.  One of my favorites so far.', '2009-04-14 11:23:47.000000', NULL, 1),
(5436337, 781791, 80104, '<td valign="top">Someoen''s got some great drawing skills.  the picture is really nice but the crayon to the bottom right is a little disctracting.</td>', 'Someoen''s got some great drawing skills.  the picture is really nice but the crayon to the bottom right is a little disctracting.', '2009-04-14 11:24:20.000000', NULL, 1),
(5436339, 780005, 80104, '<td valign="top">Nice idea, too bad the colors don''t pop out quite as much as I would like.</td>', 'Nice idea, too bad the colors don''t pop out quite as much as I would like.', '2009-04-14 11:24:39.000000', NULL, 1),
