(5436344, 781688, 80104, '<td valign="top">Hehe, interesting shot.  Just wish there was more "color" to it.  Maybe a bit brighter and less "blah"</td>', 'Hehe, interesting shot.  Just wish there was more "color" to it.  Maybe a bit brighter and less "blah"', '2009-04-14 11:27:30.000000', NULL, 1),
