(5436346, 780965, 80104, '<td valign="top">Nicely done.  Pencils aren''t too out of focus and yet a very sharp focus on the sharpener.  Simple background that brings the attention to the subjects.</td>', 'Nicely done.  Pencils aren''t too out of focus and yet a very sharp focus on the sharpener.  Simple background that brings the attention to the subjects.', '2009-04-14 11:28:11.000000', NULL, 1),
(5436347, 781799, 98339, '<td valign="top">very good idea...I have only one thing and it is "picky" your surface is quite "marred" (this is no way effects your score mind you...)</td>', 'very good idea...I have only one thing and it is "picky" your surface is quite "marred" (this is no way effects your score mind you...)', '2009-04-14 11:28:58.000000', NULL, 1),
(5436348, 781696, 80104, '<td valign="top">Nicely done.  wish the right hand wasn''t so bright though.  it''s a tad distracting.</td>', 'Nicely done.  wish the right hand wasn''t so bright though.  it''s a tad distracting.', '2009-04-14 11:29:00.000000', NULL, 1),
(5436350, 780819, 80104, '<td valign="top">haha.  Well done.  I like this shot.  the soft focus seems to work well on this one.</td>', 'haha.  Well done.  I like this shot.  the soft focus seems to work well on this one.', '2009-04-14 11:29:23.000000', NULL, 1),
