(5436363, 780746, 80104, '<td valign="top">This is a really nice shot.  I wish the black and white part near the waterfall was just a bit more clear but very very well done nonetheless.</td>', 'This is a really nice shot.  I wish the black and white part near the waterfall was just a bit more clear but very very well done nonetheless.', '2009-04-14 11:34:09.000000', NULL, 1),
(5436364, 781673, 80104, '<td valign="top">This is interesting.  Must have taken a while to get that setup.</td>', 'This is interesting.  Must have taken a while to get that setup.', '2009-04-14 11:34:27.000000', NULL, 1),
(5436365, 781324, 98339, '<td valign="top">good idea...great focus</td>', 'good idea...great focus', '2009-04-14 11:34:32.000000', NULL, 1),
(5436366, 780949, 80104, '<td valign="top">It''s a bit too abstract for my taste but interesting colors.</td>', 'It''s a bit too abstract for my taste but interesting colors.', '2009-04-14 11:34:43.000000', NULL, 1),
(5436368, 780667, 80104, '<td valign="top">Nice work.  Just wish it was a tad less saturated but a bit brighter.</td>', 'Nice work.  Just wish it was a tad less saturated but a bit brighter.', '2009-04-14 11:35:04.000000', NULL, 1),
(5436369, 781760, 98339, '<td valign="top">this is a good idea...but the white background is just to "blaring" maybe using more defused light would have worked better (mind you I know NOTHING about light sources!!)</td>', 'this is a good idea...but the white background is just to "blaring" maybe using more defused light would have worked better (mind you I know NOTHING about light sources!!)', '2009-04-14 11:35:55.000000', NULL, 1),
