(5436378, 781510, 80104, '<td valign="top">Interesting but I don''t really like the processing a whole lot.  Still a neat way to do it.</td>', 'Interesting but I don''t really like the processing a whole lot.  Still a neat way to do it.', '2009-04-14 11:38:21.000000', NULL, 1),
(5436379, 781750, 80104, '<td valign="top">Picture looks sharp and the way you''ve setup your subject is superb.  The background with the lighter bit surrounding the pencils works really well too</td>', 'Picture looks sharp and the way you''ve setup your subject is superb.  The background with the lighter bit surrounding the pencils works really well too', '2009-04-14 11:38:52.000000', NULL, 1),
(5436380, 781753, 80104, '<td valign="top">Interesting subject but I wish the image was a bit brighter.</td>', 'Interesting subject but I wish the image was a bit brighter.', '2009-04-14 11:39:10.000000', NULL, 1),
(5436381, 780788, 98339, '<td valign="top">one of these days I am going to learn how to do this...B&amp;W with color...very good</td>', 'one of these days I am going to learn how to do this...B&W with color...very good', '2009-04-14 11:39:11.000000', NULL, 1);
