(5446902, 781684, 39057, '<td valign="top">Even if this was a "picture" in the background it would not "skirt" the line on existing artwork. The addition of the additional objects...hand, pencils...would have made this 100% legal.<br/> <br/><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Yo_Spiff:</b></div><hr/><i> Definitely skirts the line on pre exisitng artwork. At least I assume it is. Might really be that scene in the background. I''m curious to see your notes on this. </i></td></tr></table></td>', 'Even if this was a "picture" in the background it would not "skirt" the line on existing artwork. The addition of the additional objects...hand, pencils...would have made this 100% legal. Originally posted by Yo_Spiff: Definitely skirts the line on pre exisitng artwork. At least I assume it is. Might really be that scene in the background. I''m curious to see your notes on this. ', '2009-04-21 12:05:13.000000', NULL, 0),
(5447197, 781487, 14476, '<td valign="top">Hey, <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=67145" rel="nofollow" target="_blank">roz</a>, congratulations on a fine entry.  Great props and excellent processing, not to mention your tremendous imagination.</td>', 'Hey,  roz, congratulations on a fine entry.  Great props and excellent processing, not to mention your tremendous imagination.', '2009-04-21 16:11:45.000000', NULL, 0),
